{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace TABLE trase-wh.maplemonk.shipment_status_mapping (SHIPPING_STATUS string(16777216),Mapped_Status string(16777216)); Insert INTO trase-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists trase-wh.maplemonk.facility_pincode (facility string,pincode string); create or replace table trase-wh.maplemonk.trase_sales_consolidated_intermediate as select cast(b.customer_id as string) customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(b.FINAL_UTM_SOURCE) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(d.order_status) as OMS_order_status ,UPPER(coalesce(b.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,d.awb) AWB ,GATEWAY PAYMENT_GATEWAY ,upper(coalesce(d.payment_mode)) Payment_Mode ,Upper(coalesce(d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,(case when b.commonsku =\'\' then null else b.commonsku end) as commonsku ,(case when b.color_sku =\'\' then null else b.color_sku end) as color_sku ,(case when b.parent_sku =\'\' then null else b.parent_sku end) as parent_sku ,upper(d.warehouse_name) WAREHOUSE ,coalesce(b.pincode,d.pincode) as pincode ,fa.pincode as source_pincode ,upper(b.source_name) Source_name ,null Mapped_Source_Name ,null Order_Type ,b.image_url ,b.PRODUCT_ID as marketplace_id ,b.marketplace as mapped_marketplace from trase-wh.maplemonk.TRASE_SHOPIFY_FACT_ITEMS b left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from trase-wh.maplemonk.trase_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from trase-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from trase-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) UNION ALL SELECT NULL AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marektplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(b.Product_Category) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,b.commonsku ,b.color_sku ,b.parent_sku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode pickup_pincode ,cast(null as string) as Source_Name ,cast(null as string) as Mapped_Source_Name ,cast(null as string) as Order_Type ,b.image_url ,b.marketplace_id ,b.mapped_marketplace FROM trase-wh.maplemonk.trase_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE NOT (LOWER(b.marketplace) LIKE \'%shopify%\') AND b.reference_code not in (select distinct order_id from maplemonk.trase_amazon_fact_items) UNION ALL SELECT cast(NULL AS string) customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, UPPER(coalesce(ufi.marketplace,\'AMAZON\')) AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL AS PHONE, afi.NAME, COALESCE(UFI.EMAIL, AFI.EMAIL) AS EMAIL, CAST(UFI.shipping_last_update_date AS timestamp) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(afi.tax, 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(UFI.order_status) AS OMS_order_status, UPPER(UFI.shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, UFI.awb AS AWB, NULL AS Payment_Gateway, UPPER(UFI.payment_mode) AS Payment_Mode, UPPER( UFI.courier) AS COURIER, UFI.dispatch_date AS DISPATCH_DATE, UFI.delivered_date AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS INT64) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status,UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(AFI.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, UPPER(AFI.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY ,AFI.commonsku ,AFI.color_sku ,AFI.parent_sku ,UPPER(UFI.warehouse_name) AS WAREHOUSE ,COALESCE(AFI.pincode, UFI.pincode) AS pincode ,fa.pincode source_pincode ,cast(null as string) as Source_Name ,cast(null as string) as Mapped_Source_Name ,cast(null as string) as Order_Type ,afi.image_url ,afi.product_id as marketplace_id ,\'AMAZON\' as mapped_marketplace FROM trase-wh.maplemonk.TRASE_AMAZON_FACT_ITEMS AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM trase-wh.maplemonk.TRASE_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(AFI.order_id as string) = cast(UFI.reference_code as string) AND cast(AFI.sku as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from trase-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM trase-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) ; CREATE OR REPLACE TABLE trase-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM trase-wh.maplemonk.trase_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM trase-wh.maplemonk.trase_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE trase-wh.maplemonk.trase_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, ifnull(i.available_inventory,0) as Available_Inventory_Yesterday, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM trase-wh.maplemonk.trase_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM trase-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM trase-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email left join (SELECT * FROM maplemonk.trase_inventory_fact_items WHERE data_fetch_date = (SELECT MAX(data_fetch_date) FROM maplemonk.trase_inventory_fact_items) ) i on m.sku = i.sku ; ALTER TABLE trase-wh.maplemonk.trase_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE trase-wh.maplemonk.trase_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE trase-wh.maplemonk.trase_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM trase-wh.maplemonk.trase_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE trase-wh.maplemonk.trase_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE trase-wh.maplemonk.trase_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM trase-wh.maplemonk.trase_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE trase-wh.maplemonk.trase_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM trase-wh.maplemonk.trase_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE trase-wh.maplemonk.trase_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE trase-wh.maplemonk.trase_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM trase-wh.maplemonk.trase_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE trase-wh.maplemonk.trase_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            